import { createHash } from 'node:crypto';

import type { IconRecord } from './types.js';
import { validateIconCatalog } from './validation.js';

export const generatedArtifactPaths = [
  'packages/icons/src/generated/catalog.ts',
  'tooling/icon-pipeline/generated/source-manifest.json',
  'tooling/icon-pipeline/generated/output-manifest.json',
  'tooling/icon-pipeline/generated/review-index.html',
] as const;

export type GeneratedArtifactPath = (typeof generatedArtifactPaths)[number];
export type GeneratedIconArtifacts = Readonly<Record<GeneratedArtifactPath, string>>;

const runtimePath = generatedArtifactPaths[0];
const sourceManifestPath = generatedArtifactPaths[1];
const outputManifestPath = generatedArtifactPaths[2];
const reviewPath = generatedArtifactPaths[3];

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function canonicalValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonicalValue);
  if (typeof value !== 'object' || value === null) return value;
  return Object.fromEntries(
    Object.keys(value)
      .sort(compareText)
      .map((key) => [key, canonicalValue((value as Record<string, unknown>)[key])]),
  );
}

function canonicalJson(value: unknown): string {
  return `${JSON.stringify(canonicalValue(value), undefined, 2)}\n`;
}

function sha256(value: string): string {
  return createHash('sha256').update(value, 'utf8').digest('hex');
}

function runtimeCatalogSource(catalog: readonly IconRecord[]): string {
  const records = catalog.map(({ id, direction, primitives }) => ({
    name: id,
    direction,
    primitives,
  }));
  return [
    '// Generated by the private Wayglass icon pipeline. Do not edit.',
    '',
    `export const generatedIconCatalog = ${JSON.stringify(records, undefined, 2)} as const;`,
    '',
    "export type GeneratedIconName = (typeof generatedIconCatalog)[number]['name'];",
    '',
  ].join('\n');
}

function pathData(icon: IconRecord): string {
  return icon.primitives
    .filter((primitive) => primitive.type === 'path')
    .map((primitive) =>
      primitive.commands
        .map((command) => {
          switch (command.command) {
            case 'move-to':
              return `M ${command.x} ${command.y}`;
            case 'line-to':
              return `L ${command.x} ${command.y}`;
            case 'arc-to':
              return `A ${command.radiusX} ${command.radiusY} ${command.rotation} ${command.largeArc ? 1 : 0} ${command.sweep ? 1 : 0} ${command.x} ${command.y}`;
            case 'close-path':
              return 'Z';
          }
        })
        .join(' '),
    )
    .join(' ');
}

function symbolMarkup(icon: IconRecord): string {
  const primitives = icon.primitives
    .map((primitive) => {
      if (primitive.type === 'path') {
        return `<path d="${pathData({ ...icon, primitives: [primitive] })}" fill="${primitive.fill}" stroke="${primitive.stroke}" />`;
      }
      return `<circle cx="${primitive.centerX}" cy="${primitive.centerY}" r="${primitive.radius}" fill="${primitive.fill}" stroke="${primitive.stroke}" />`;
    })
    .join('');
  return `<symbol id="wg-review-icon-${icon.id}" viewBox="0 0 24 24">${primitives}</symbol>`;
}

function decorativeSvg(icon: IconRecord, size: string, direction: 'ltr' | 'rtl'): string {
  return `<figure class="sample" data-size="${size}" dir="${direction}"><svg class="icon icon--${size}" data-direction="${icon.direction}" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#wg-review-icon-${icon.id}" /></svg><figcaption>${size}, ${direction.toUpperCase()}</figcaption></figure>`;
}

function reviewCard(icon: IconRecord): string {
  const samples = ['compact', 'standard', 'prominent']
    .flatMap((size) =>
      (['ltr', 'rtl'] as const).map((direction) => decorativeSvg(icon, size, direction)),
    )
    .join('');
  return `<article class="icon-card" data-icon="${icon.id}" data-direction="${icon.direction}"><header><h3>${icon.id}</h3><span>${icon.direction}</span></header><div class="sample-grid">${samples}</div><dl><div><dt>Category</dt><dd>${icon.category}</dd></div><div><dt>Accessible use</dt><dd>${icon.accessibleUse}</dd></div></dl></article>`;
}

function themeReview(catalog: readonly IconRecord[], theme: 'light' | 'dark'): string {
  return `<section class="theme" data-theme="${theme}" data-wg-theme="wayglass-${theme}" aria-labelledby="${theme}-heading"><h2 id="${theme}-heading">${theme[0]!.toUpperCase()}${theme.slice(1)} review</h2><div class="catalog">${catalog.map(reviewCard).join('')}</div></section>`;
}

function reviewIndexHtml(catalog: readonly IconRecord[]): string {
  const fallback = catalog[0]!;
  const close = catalog.find(({ id }) => id === 'close') ?? fallback;
  const menu = catalog.find(({ id }) => id === 'menu') ?? fallback;
  const refresh = catalog.find(({ id }) => id === 'refresh') ?? fallback;
  const named =
    catalog.find(({ id }) => id === 'arrow-inline-start') ??
    catalog.find(({ direction }) => direction === 'mirrors-in-rtl') ??
    fallback;
  const symbols = catalog.map(symbolMarkup).join('');

  // Grid minima, review widths, and preview dimensions below are private mechanics of this
  // generated evidence page. Intentional color, spacing, border, radius, and icon-size choices use
  // accepted Wayglass tokens so review stays coupled to the system it evaluates.
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Wayglass icon review index</title>
<link rel="stylesheet" href="../../../packages/tokens/dist/tokens.css" />
<link rel="stylesheet" href="../../../packages/themes/dist/themes.css" />
<style>
:root{font-family:ui-sans-serif,system-ui,sans-serif;line-height:1.5}*{box-sizing:border-box}body{margin:0;background:var(--wg-color-semantic-surface-canvas);color:var(--wg-color-semantic-text-primary)}main{display:grid;gap:var(--wg-space-reference-6);max-inline-size:96rem;margin-inline:auto;padding:var(--wg-space-semantic-page-comfortable)}h1,h2,h3,p{margin-block-start:0}.intro{max-inline-size:70ch}.theme{padding:var(--wg-space-reference-4);border:var(--wg-border-width-strong) solid var(--wg-color-semantic-border-strong);border-radius:var(--wg-shape-radius-panel);background:var(--wg-color-semantic-surface-panel);color:var(--wg-color-semantic-text-primary)}.catalog{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,18rem),1fr));gap:var(--wg-space-reference-4)}.icon-card{min-inline-size:0;padding:var(--wg-space-reference-4);border:var(--wg-border-width-standard) solid var(--wg-color-semantic-border-subtle);border-radius:var(--wg-shape-radius-control)}.icon-card header{display:flex;flex-wrap:wrap;justify-content:space-between;gap:var(--wg-space-reference-2)}.icon-card h3{overflow-wrap:anywhere}.icon-card header span{font-family:ui-monospace,monospace;font-size:.75rem}.sample-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--wg-space-reference-2)}.sample{display:grid;place-items:center;gap:var(--wg-space-reference-1);min-block-size:4.75rem;margin:0;padding:var(--wg-space-reference-2);border:var(--wg-border-width-standard) dashed var(--wg-color-semantic-border-subtle);border-radius:var(--wg-shape-radius-control)}.sample figcaption{font-size:.7rem}.icon{display:block;overflow:visible;color:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;transform-box:fill-box;transform-origin:center}.icon--compact{inline-size:var(--wg-component-icon-size-compact);block-size:var(--wg-component-icon-size-compact)}.icon--standard{inline-size:var(--wg-component-icon-size-standard);block-size:var(--wg-component-icon-size-standard)}.icon--prominent{inline-size:var(--wg-component-icon-size-prominent);block-size:var(--wg-component-icon-size-prominent)}[dir="rtl"] .icon[data-direction="mirrors-in-rtl"]{transform:scaleX(-1)}dl{display:grid;gap:var(--wg-space-reference-1);margin-block-end:0;font-size:.8rem}dl div{display:flex;flex-wrap:wrap;justify-content:space-between;gap:var(--wg-space-reference-1) var(--wg-space-reference-4);min-inline-size:0}dd{margin-inline-start:0;overflow-wrap:anywhere}dt{font-weight:700}.semantics{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,18rem),1fr));gap:var(--wg-space-reference-4)}.semantics section{padding:var(--wg-space-reference-4);border:var(--wg-border-width-strong) solid var(--wg-color-semantic-border-strong);border-radius:var(--wg-shape-radius-control);background:var(--wg-color-semantic-surface-panel)}.controls{display:flex;flex-wrap:wrap;gap:var(--wg-space-reference-3)}.controls button{display:inline-flex;align-items:center;gap:var(--wg-space-reference-2);min-block-size:var(--wg-size-touch-minimum);padding:var(--wg-space-reference-2) var(--wg-space-reference-3);border:var(--wg-border-width-strong) solid var(--wg-color-semantic-border-strong);border-radius:var(--wg-shape-radius-control);background:var(--wg-color-semantic-surface-inset);color:inherit;font:inherit}.controls .icon{inline-size:var(--wg-component-icon-size-standard);block-size:var(--wg-component-icon-size-standard)}.named-reference{display:flex;flex-wrap:wrap;align-items:center;gap:var(--wg-space-reference-3)}.named-reference .icon{inline-size:var(--wg-component-icon-size-prominent);block-size:var(--wg-component-icon-size-prominent)}.missing{display:grid;place-items:center;min-block-size:4rem;border:var(--wg-border-width-strong) dashed var(--wg-color-semantic-border-strong);border-radius:var(--wg-shape-radius-control);font-weight:700}.visually-hidden{position:absolute;inline-size:1px;block-size:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}@media(max-width:24rem){main,.theme{padding:var(--wg-space-reference-3)}.sample-grid{grid-template-columns:1fr}}@media(forced-colors:active){body,.theme,.semantics section{background:Canvas;color:CanvasText}.theme,.icon-card,.sample,.semantics section,.controls button,.missing{border-color:CanvasText}.icon{color:CanvasText;forced-color-adjust:auto}}
</style>
</head>
<body>
<svg class="visually-hidden" aria-hidden="true" focusable="false"><defs>${symbols}</defs></svg>
<main>
<header><p>Private build and validation tooling</p><h1>Icon review index</h1><p class="intro">Every glyph appears at compact, standard, and prominent sizes in both reading directions. Text identifies every state so review never depends on icon recognition or color.</p></header>
${themeReview(catalog, 'light')}
${themeReview(catalog, 'dark')}
<div class="semantics">
<section aria-labelledby="named-heading"><h2 id="named-heading">Named reference</h2><figure class="named-reference"><svg class="icon" data-direction="${named.direction}" viewBox="0 0 24 24" role="img" aria-labelledby="named-title named-description" focusable="false"><title id="named-title">Inline-start reference</title><desc id="named-description">A tooling reference that mirrors in right-to-left layouts when its reviewed direction requires it.</desc><use href="#wg-review-icon-${named.id}" /></svg><figcaption>Reference only; application meaning still requires text.</figcaption></figure></section>
<section aria-labelledby="control-heading"><h2 id="control-heading">Owning controls</h2><div class="controls"><button type="button"><svg class="icon" data-direction="${refresh.direction}" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#wg-review-icon-${refresh.id}" /></svg><span>Refresh records</span></button><button type="button"><svg class="icon" data-direction="${menu.direction}" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#wg-review-icon-${menu.id}" /></svg><span>Open navigation</span></button><button type="button"><svg class="icon" data-direction="${close.direction}" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><use href="#wg-review-icon-${close.id}" /></svg><span>Close review</span></button></div></section>
<section aria-labelledby="absent-heading"><h2 id="absent-heading">Icon-absent task</h2><p>Every task remains explicit when icons are unavailable.</p><div class="controls"><button type="button">Refresh records</button><button type="button">Open navigation</button><button type="button">Close review</button></div></section>
<section aria-labelledby="missing-heading"><h2 id="missing-heading">Missing preview</h2><div class="missing" role="img" aria-label="Preview unavailable for requested icon">Unavailable preview</div></section>
</div>
</main>
</body>
</html>
`;
}

export function generateIconArtifacts(input: unknown): GeneratedIconArtifacts {
  const catalog = [...validateIconCatalog(input)].sort((left, right) =>
    compareText(left.id, right.id),
  );
  const sourceFingerprint = sha256(canonicalJson(catalog));
  const runtimeCatalog = runtimeCatalogSource(catalog);
  const reviewIndex = reviewIndexHtml(catalog);
  const sourceManifest = canonicalJson({
    catalogSchemaVersion: 1,
    contractRevision: 1,
    iconCount: catalog.length,
    icons: catalog.map((icon) => ({
      accessibleUse: icon.accessibleUse,
      category: icon.category,
      direction: icon.direction,
      fingerprint: sha256(canonicalJson(icon)),
      id: icon.id,
      provenance: icon.provenance,
    })),
    sourceFingerprint,
  });
  const authenticated = [
    [runtimePath, runtimeCatalog],
    [sourceManifestPath, sourceManifest],
    [reviewPath, reviewIndex],
  ] as const;
  const outputManifest = canonicalJson({
    artifacts: authenticated.map(([path, contents]) => ({
      bytes: Buffer.byteLength(contents),
      path,
      sha256: sha256(contents),
    })),
    generator: 'wayglass-icon-pipeline',
    generatorSchemaVersion: 1,
    sourceFingerprint,
  });

  return Object.freeze({
    [runtimePath]: runtimeCatalog,
    [sourceManifestPath]: sourceManifest,
    [outputManifestPath]: outputManifest,
    [reviewPath]: reviewIndex,
  }) as GeneratedIconArtifacts;
}
